import { describe, expect, it } from "vitest";
import baseline from "./baseline/reports.json";

/**
 * Guards the report screens' externally-visible contract during the CP-5
 * migration to the config-driven engine.
 *
 * These screens are the highest-stakes in the app: they POST a filter payload,
 * so a difference as small as "" vs [] or "All" vs null makes the backend
 * return different rows, and they produce Excel files that go to customers.
 * Neither failure surfaces in a build or a render test — the report simply
 * shows the wrong numbers.
 *
 * The baseline is generated by scripts/extractReportBaseline.mjs from the
 * CURRENT (pre-migration) code. As each screen moves to a config, add its
 * assertion here comparing config.buildPayload(...) and the derived export
 * headers against the recorded values.
 */

const byFile = (suffix) => baseline.find((r) => r.file.endsWith(suffix));

describe("report baseline integrity", () => {
  it("captured a meaningful number of screens", () => {
    expect(baseline.length).toBeGreaterThanOrEqual(20);
  });

  it("every recorded payload has at least one key", () => {
    for (const rec of baseline) {
      for (const p of rec.payloads) {
        expect(p.pairs.length, `${rec.file} ${p.name}`).toBeGreaterThan(0);
      }
    }
  });

  it("every export records a filename and headers in order", () => {
    for (const rec of baseline) {
      for (const e of rec.exports) {
        expect(e.fileName, rec.file).toBeTruthy();
        expect(e.headers.length, rec.file).toBeGreaterThan(0);
        expect(e.headers.length).toBe(e.fields.length);
      }
    }
  });

  it("no export has duplicate column headers", () => {
    for (const rec of baseline) {
      for (const e of rec.exports) {
        const dupes = e.headers.filter((h, i) => e.headers.indexOf(h) !== i);
        expect(dupes, `${rec.file} -> ${e.fileName}`).toEqual([]);
      }
    }
  });
});

describe("payload duplication (pre-existing drift risk)", () => {
  // Several screens build the same payload twice -- once for the table fetch
  // and once for the Excel export -- by copy-paste. They agree today, but
  // nothing keeps them in sync; editing one filter silently desynchronises the
  // table from the spreadsheet. Collapsing them into a single buildPayload is
  // a concrete win of the engine, so this pins the current agreement.
  //
  // Only payloads with the SAME KEY SET are compared. A different key set means
  // a different operation (UpdateWeight has single vs bulk; CorporateBilling
  // has three distinct calls), not a duplicate.
  const sig = (p) => p.pairs.map((x) => x.key).join(",");
  const shape = (p) => p.pairs.map((x) => `${x.key}=${x.expr}`).join("|");

  const duplicated = baseline.flatMap((rec) => {
    const groups = new Map();
    for (const p of rec.payloads) {
      const k = sig(p);
      groups.set(k, [...(groups.get(k) ?? []), p]);
    }
    return [...groups.values()]
      .filter((g) => g.length > 1)
      .map((g) => [rec.file.split("/").pop(), g]);
  });

  // Screens whose export-banner copy has ALREADY drifted from the query
  // payload. Tracked explicitly rather than asserted equal, so the suite stays
  // green while the drift stays visible. Each is fixed by construction when the
  // screen moves to a single buildPayload.
  const KNOWN_DRIFT = new Set(["CustomerPerformance.jsx"]);

  it("finds screens that build the same payload more than once", () => {
    expect(duplicated.length).toBeGreaterThan(0);
  });

  it.each(duplicated.filter(([n]) => !KNOWN_DRIFT.has(n)))(
    "%s: duplicated payloads stay identical",
    (_name, group) => {
      const [first, ...rest] = group;
      for (const other of rest) expect(shape(other)).toBe(shape(first));
    }
  );

  it("CustomerPerformance's export banner has lost the query's fallbacks", () => {
    // Query payload:  mode: SelectedMode?.value || "",  region: [...] || []
    // Banner payload: mode: SelectedMode?.value,        region: [...]
    // JSON.stringify drops undefined values, so with no mode/region selected
    // the spreadsheet's "filters applied" header omits those fields entirely
    // instead of showing them empty. Exported rows are unaffected.
    const rec = byFile("CustomerPerformance.jsx");
    const [query, banner] = rec.payloads;
    expect(query.pairs.find((p) => p.key === "mode").expr).toContain('|| ""');
    expect(banner.pairs.find((p) => p.key === "mode").expr).not.toContain("||");
  });
});

describe("AttemptWise* Excel filter banner reports the wrong field", () => {
  // Documents a real defect found while building this baseline.
  //
  // Both AttemptWise screens query with `payment_mode: PaymentMode?.value`,
  // where PaymentMode is bound to the UI. The object handed to exportToExcel
  // as the spreadsheet's "filters applied" banner instead reads
  // `mode: SelectedMode?.value` -- and SelectedMode is declared with useState()
  // and never assigned, so the banner always records an empty string.
  //
  // The exported ROWS are correct (they come from already-fetched BookingData);
  // only the provenance header is wrong. Migrating these screens to a single
  // buildPayload fixes it by construction. Until then, this test documents the
  // behaviour so the fix is a deliberate change rather than an accident.
  const files = ["AttemptWiseOperationPickupReport.jsx", "AttemptWiseCustomerPickupReport.jsx"];

  it.each(files)("%s still has the mismatch", (name) => {
    const rec = byFile(name);
    const keys = rec.payloads.map((p) => p.pairs.map((x) => x.key));
    const query = keys.find((k) => k.includes("payment_mode"));
    const banner = keys.find((k) => k.includes("mode") && !k.includes("payment_mode"));
    expect(query, "query payload should filter on payment_mode").toBeTruthy();
    expect(banner, "banner payload should still use the stale `mode` key").toBeTruthy();
  });
});

describe("CODReport — first migration target", () => {
  const cod = byFile("CODReport.jsx");

  it("posts to COD_UPLOAD_REPORTS", () => {
    expect(cod.endpoints).toContain("COD_UPLOAD_REPORTS");
  });

  it("sends exactly start_date, end_date, customer_name", () => {
    expect(cod.payloads[0].pairs.map((p) => p.key)).toEqual([
      "start_date",
      "end_date",
      "customer_name",
    ]);
  });

  it('defaults customer_name to "All"', () => {
    const customer = cod.payloads[0].pairs.find((p) => p.key === "customer_name");
    expect(customer.expr).toContain('"All"');
  });

  it("exports 12 columns in a fixed order to COD_Details", () => {
    const [exp] = cod.exports;
    expect(exp.fileName).toBe("COD_Details");
    expect(exp.headers).toEqual([
      "AWB No",
      "Pickup Pincode",
      "Drop Pincode",
      "Weight (Kg)",
      "Shipment Value",
      "Payment Mode",
      "Customer Name",
      "Origin SC",
      "Consignee City",
      "Consignee State",
      "Date",
      "COD Amount",
    ]);
  });
});
